package cloud.trotter.census.server.db

import cloud.trotter.census.server.EpochKey
import cloud.trotter.census.server.Epochs
import cloud.trotter.census.server.HashKeying
import cloud.trotter.census.server.TagPurpose
import java.sql.Connection
import java.time.LocalDate
import java.util.UUID

/**
 * The epoch keys (#86, ADR-0011 §21). Each epoch has its own random 32-byte key, generated by the server the first
 * time a row of that epoch is tagged, and stored in `epoch_keys` wrapped (AES-GCM) under a key derived from the
 * pepper. A dump or backup without the pepper therefore holds no usable epoch key.
 *
 * Destruction: a key is deleted once its epoch is older than the previous one ([Epochs.live]). Nothing can
 * re-derive it (it is random, not derived from the pepper), so the rows tagged under it can no longer be tied to an
 * install by anyone, the operator included, once the last backup holding the wrapped key has expired. Retention
 * deletes those rows anyway: every content table keeps at most 30 days, and a key outlives its epoch by at least one
 * full epoch.
 */
internal object EpochKeyStore {
    /**
     * The keys that exist for the live epochs on [today], newest first. Never creates one: an epoch without a key has
     * no rows. A key that does not open under the configured pepper fails closed ([cloud.trotter.census.server.EpochKeyUnwrapException]).
     */
    fun Connection.liveKeys(keying: HashKeying, today: LocalDate): List<EpochKey> {
        val live = Epochs.live(today)
        return prepareStatement("SELECT epoch, wrapped FROM epoch_keys WHERE epoch BETWEEN ? AND ? ORDER BY epoch DESC").use { statement ->
            statement.setInt(1, live.first)
            statement.setInt(2, live.last)
            statement.executeQuery().use { rows ->
                buildList { while (rows.next()) add(EpochKey.unwrap(keying, rows.getInt(1), rows.getBytes(2))) }
            }
        }
    }

    /**
     * The key rows of [epoch] are tagged under, created on first use. Refuses an epoch outside [Epochs.live]: a row is
     * never tagged under a key that is already due for destruction, nor under one far in the future. Concurrent first
     * uses agree: the losing insert waits for the winner's commit and then reads its key.
     */
    fun Connection.keyForTagging(keying: HashKeying, epoch: Int, today: LocalDate): EpochKey {
        require(epoch in Epochs.live(today)) { "epoch outside the live window" }
        read(keying, epoch)?.let { return it }
        val (key, wrapped) = EpochKey.generate(keying, epoch)
        val inserted = prepareStatement("INSERT INTO epoch_keys (epoch, wrapped) VALUES (?, ?) ON CONFLICT (epoch) DO NOTHING").use { statement ->
            statement.setInt(1, epoch)
            statement.setBytes(2, wrapped)
            statement.executeUpdate()
        }
        if (inserted == 1) {
            destroyExpired(today)
            return key
        }
        return read(keying, epoch) ?: error("Missing epoch key")
    }

    /** Creates the current and next epochs' keys if missing (the lifecycle sweep runs this ahead of ingest). */
    fun Connection.ensureAhead(keying: HashKeying, today: LocalDate) {
        val current = Epochs.of(today)
        keyForTagging(keying, current, today)
        keyForTagging(keying, current + 1, today)
    }

    /** Deletes every key older than the previous epoch; returns how many went. */
    fun Connection.destroyExpired(today: LocalDate): Int =
        update("DELETE FROM epoch_keys WHERE epoch < ?", Epochs.live(today).first)

    fun Connection.expiredCount(today: LocalDate): Long =
        select("SELECT count(*) FROM epoch_keys WHERE epoch < ?", Epochs.live(today).first) { it.getLong(1) } ?: 0L

    private fun Connection.read(keying: HashKeying, epoch: Int): EpochKey? =
        prepareStatement("SELECT wrapped FROM epoch_keys WHERE epoch = ?").use { statement ->
            statement.setInt(1, epoch)
            statement.executeQuery().use { rows -> if (rows.next()) EpochKey.unwrap(keying, epoch, rows.getBytes(1)) else null }
        }
}

/** An epoch tag and the epoch it belongs to, as stored beside a content row (#86). */
internal data class EpochTag(val epoch: Int, val tag: String)

/**
 * Tags rows within one transaction (#86): each row under the epoch of the day it describes, keys read or created once
 * per epoch. [today] is the receipt day, which bounds the epochs a key may be created for.
 */
internal class Tagger(private val connection: Connection, private val keying: HashKeying, private val today: LocalDate) {
    private val keys = HashMap<Int, EpochKey>()

    fun tag(purpose: TagPurpose, installId: UUID, objectKey: String, day: LocalDate): EpochTag {
        val epoch = Epochs.of(day)
        val key = keys.getOrPut(epoch) { with(EpochKeyStore) { connection.keyForTagging(keying, epoch, today) } }
        return EpochTag(epoch, key.tag(purpose, installId, objectKey))
    }
}

/**
 * The content tables keyed by epoch tags instead of the install id (#86). Each knows how to list the objects stored
 * under one epoch, from which one install's tags in that epoch are recomputed.
 */
internal enum class TaggedTable(val table: String, val purpose: TagPurpose, private val objects: String?) {
    HEALTH("health_daily", TagPurpose.HEALTH, null),
    TOKENS("token_sightings_v5", TagPurpose.TOKEN,
        "SELECT DISTINCT hash_domain::text || ':' || filter_rev::text || ':' || token_hash FROM token_sightings_v5 WHERE epoch = ?"),
    CLUSTERS("cluster_sightings_v5", TagPurpose.CLUSTER,
        "SELECT DISTINCT fingerprint::text FROM cluster_sightings_v5 WHERE epoch = ?"),
    ;

    /**
     * [installId]'s tags in this table under [key]: one per object stored in that epoch (a table without objects has
     * one tag). Rows of other installs never match (a tag covers the install id), and rows under a destroyed key are
     * never found: no live key reproduces their tags.
     */
    fun tags(connection: Connection, key: EpochKey, installId: UUID): List<String> {
        val objectKeys = if (objects == null) listOf("") else connection.prepareStatement(objects).use { statement ->
            statement.setInt(1, key.epoch)
            statement.executeQuery().use { rows -> buildList { while (rows.next()) add(rows.getString(1)) } }
        }
        return objectKeys.map { key.tag(purpose, installId, it) }
    }

    companion object {
        /** Tags matched per statement, so one install's rows are found with bounded parameter arrays. */
        const val CHUNK: Int = 5000
    }
}

/**
 * Runs [statement] once per chunk of [installId]'s tags in [table], for every live key; [bind] orders the parameters
 * from the epoch and the tag array. Returns the summed update counts.
 */
internal fun Connection.forInstallTags(
    keys: List<EpochKey>,
    table: TaggedTable,
    installId: UUID,
    statement: String,
    bind: (epoch: Int, tags: java.sql.Array) -> Array<Any?> = { epoch, tags -> arrayOf(epoch, tags) },
): Int {
    var total = 0
    for (key in keys) {
        for (chunk in table.tags(this, key, installId).chunked(TaggedTable.CHUNK)) {
            val tags = createArrayOf("text", chunk.toTypedArray())
            try {
                total += update(statement, *bind(key.epoch, tags))
            } finally {
                tags.free()
            }
        }
    }
    return total
}

/**
 * Deletes [installId]'s token and cluster sightings in every live epoch (#86): withdrawal, data deletion and
 * revocation. The caller holds the install row lock, so no new sighting of it can appear meanwhile.
 */
internal fun Connection.deleteSightings(keys: List<EpochKey>, installId: UUID): Map<String, Int> =
    listOf(TaggedTable.TOKENS, TaggedTable.CLUSTERS).associate { table ->
        table.table to forInstallTags(keys, table, installId,
            "DELETE FROM ${table.table} WHERE epoch = ? AND install_tag = ANY(?::bpchar[])")
    }

/** Marks [installId]'s live sightings trusted or not, with the installs row in the same transaction (#86). */
internal fun Connection.markSightingsTrusted(keys: List<EpochKey>, installId: UUID, trusted: Boolean): Int =
    listOf(TaggedTable.TOKENS, TaggedTable.CLUSTERS).sumOf { table ->
        forInstallTags(keys, table, installId,
            "UPDATE ${table.table} SET trusted = ? WHERE epoch = ? AND install_tag = ANY(?::bpchar[])") { epoch, tags ->
            arrayOf(trusted, epoch, tags)
        }
    }
